import functools
import time

import jwt
from flask import current_app, g, request

from app.errors import APIError

_rate_limit_store = {}


def generate_token(user_id, token_type="access"):
    from datetime import datetime, timedelta, timezone

    now = datetime.now(timezone.utc)
    if token_type == "access":
        expires_delta = timedelta(
            seconds=current_app.config["JWT_ACCESS_TOKEN_EXPIRES"]
        )
    else:
        expires_delta = timedelta(
            seconds=current_app.config["JWT_REFRESH_TOKEN_EXPIRES"]
        )

    payload = {
        "sub": user_id,
        "type": token_type,
        "iat": now,
        "exp": now + expires_delta,
    }
    return jwt.encode(
        payload,
        current_app.config["SECRET_KEY"],
        algorithm=current_app.config["JWT_ALGORITHM"],
    )


def decode_token(token, token_type=None):
    try:
        payload = jwt.decode(
            token,
            current_app.config["SECRET_KEY"],
            algorithms=[current_app.config["JWT_ALGORITHM"]],
        )
        if token_type and payload.get("type") != token_type:
            raise APIError("Invalid token type", 401)
        return payload
    except jwt.ExpiredSignatureError:
        raise APIError("Token has expired", 401)
    except jwt.InvalidTokenError:
        raise APIError("Invalid token", 401)


def login_required(f):
    @functools.wraps(f)
    def decorated(*args, **kwargs):
        from app.models import User

        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            raise APIError("Missing or invalid Authorization header", 401)

        token = auth_header.split(" ", 1)[1]
        payload = decode_token(token, token_type="access")
        user = User.query.get(payload["sub"])
        if not user:
            raise APIError("User not found", 401)

        g.current_user = user
        return f(*args, **kwargs)

    return decorated


def check_rate_limit(key, max_attempts, window_seconds):
    now = time.time()
    store = _rate_limit_store

    if key not in store:
        store[key] = []

    store[key] = [t for t in store[key] if t > now - window_seconds]

    if len(store[key]) >= max_attempts:
        raise APIError("Too many requests. Please try again later.", 429)

    store[key].append(now)

import re

from marshmallow import Schema, ValidationError, fields, validates


def validate_non_empty(value, field_name):
    if not value or not value.strip():
        raise ValidationError(f"{field_name} must not be empty")


class RegisterSchema(Schema):
    username = fields.Str(required=True)
    email = fields.Email(required=True)
    password = fields.Str(required=True)

    @validates("username")
    def validate_username(self, value):
        validate_non_empty(value, "Username")
        if len(value) < 3 or len(value) > 80:
            raise ValidationError("Username must be between 3 and 80 characters")
        if not re.match(r"^[a-zA-Z0-9_]+$", value):
            raise ValidationError(
                "Username must contain only letters, numbers, and underscores"
            )

    @validates("password")
    def validate_password(self, value):
        validate_non_empty(value, "Password")
        if len(value) < 6:
            raise ValidationError("Password must be at least 6 characters")


class LoginSchema(Schema):
    username = fields.Str(required=True)
    password = fields.Str(required=True)

    @validates("username")
    def validate_username(self, value):
        validate_non_empty(value, "Username")

    @validates("password")
    def validate_password(self, value):
        validate_non_empty(value, "Password")


class RefreshSchema(Schema):
    refresh_token = fields.Str(required=True)


class ItemSchema(Schema):
    name = fields.Str(required=True)
    description = fields.Str(allow_none=True, load_default=None)

    @validates("name")
    def validate_name(self, value):
        validate_non_empty(value, "Name")
        if len(value) > 200:
            raise ValidationError("Name must not exceed 200 characters")


def validate_request(schema, data):
    try:
        return schema.load(data)
    except ValidationError as e:
        from app.errors import APIError

        raise APIError(str(e.messages), 422)

from flask import jsonify


class APIError(Exception):
    def __init__(self, message, status_code=400, details=None):
        super().__init__(message)
        self.message = message
        self.status_code = status_code
        self.details = details


def register_error_handlers(app):
    @app.errorhandler(APIError)
    def handle_api_error(error):
        response = {"error": error.message}
        if error.details:
            response["details"] = error.details
        return jsonify(response), error.status_code

    @app.errorhandler(404)
    def handle_not_found(error):
        return jsonify({"error": "Resource not found"}), 404

    @app.errorhandler(405)
    def handle_method_not_allowed(error):
        return jsonify({"error": "Method not allowed"}), 405

    @app.errorhandler(500)
    def handle_internal_error(error):
        return jsonify({"error": "Internal server error"}), 500

    @app.errorhandler(413)
    def handle_request_too_large(error):
        return jsonify({"error": "Request too large"}), 413

from flask import current_app, request

from app.errors import APIError


def paginate(query, schema=None):
    try:
        page = int(request.args.get("page", 1))
        per_page = int(request.args.get("per_page", current_app.config["DEFAULT_PAGE_SIZE"]))
    except (ValueError, TypeError):
        raise APIError("Invalid pagination parameters", 400)

    if page < 1:
        raise APIError("Page must be a positive integer", 400)

    if per_page < 1 or per_page > current_app.config["MAX_PAGE_SIZE"]:
        raise APIError(
            f"per_page must be between 1 and {current_app.config['MAX_PAGE_SIZE']}",
            400,
        )

    paginated = query.paginate(page=page, per_page=per_page, error_out=False)

    items = paginated.items
    if schema:
        items = [schema.dump(item) for item in items]

    return {
        "items": items,
        "pagination": {
            "page": paginated.page,
            "per_page": paginated.per_page,
            "total": paginated.total,
            "pages": paginated.pages,
            "has_prev": paginated.has_prev,
            "has_next": paginated.has_next,
        },
    }

